### Python

```python
# -*- coding: utf-8 -*-
import sys

def solve():
    it = iter(sys.stdin.read().strip().split())
    T = int(next(it))
    out = []
    for _ in range(T):
        n = int(next(it)); l = int(next(it)); r = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        mn = None  # 全局最小子段和
        f = 0      # 以当前结尾的最小子段和
        for x in a:
            # 计算 b_k
            if l <= x <= r:
                b = min(x - l + 1, r - x + 1)
            else:
                b = 0
            c = b - 1
            # Kadane 最小子段和：f_i = min(c_i, f_{i-1} + c_i)
            if f + c < c:
                f = f + c
            else:
                f = c
            if mn is None or f < mn:
                mn = f
        ans = n + mn
        out.append(str(ans))
    print("\n".join(out))

if __name__ == "__main__":
    solve()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sbAll = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) sbAll.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(sbAll.toString());

        int T = Integer.parseInt(st.nextToken());
        StringBuilder out = new StringBuilder();

        while (T-- > 0) {
            int n = Integer.parseInt(st.nextToken());
            int l = Integer.parseInt(st.nextToken());
            int r = Integer.parseInt(st.nextToken());
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());

            long mn = Long.MAX_VALUE; // 全局最小子段和
            long f = 0;               // 以当前结尾的最小子段和
            for (int i = 0; i < n; i++) {
                int x = a[i];
                int b = 0;
                if (l <= x && x <= r) {
                    int t1 = x - l + 1;
                    int t2 = r - x + 1;
                    b = Math.min(t1, t2);
                }
                int c = b - 1;
                long cand1 = (long)c;
                long cand2 = f + c;
                f = Math.min(cand1, cand2);
                if (f < mn) mn = f;
            }
            long ans = n + mn;
            out.append(ans).append('\n');
        }
        System.out.print(out.toString());
    }
}
